  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'إذا كان علي أطول من حسن، وحسن أطول من محمد، فمن هو الأقصر بين الثلاثة؟', '["علي","محمد","حسن","لا يمكن التحديد"]'::jsonb, 1, 20, 164, 'multi', 'بما أن علي > حسن وحسن > محمد، فإن ترتيب الطول التنازلي هو علي ثم حسن ثم محمد، بالتالي محمد هو الأقصر.', 'beginner', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'اختبارات التفكير الاستنتاجي - المنهجية المنطقية', 'LOG-0041', true, 1),
  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'إذا كانت جميع الأسماك تعيش في الماء، والدلفين يعيش في الماء، فهل الدلفين سمكة حتماً؟', '["ليس بالضرورة (قد تكون كائنات أخرى كالذئاب المائية أو الثدييات)","نعم حتماً","لا أبداً","الدلفين حشرة"]'::jsonb, 0, 20, 165, 'multi', 'مغالطة عدم استغراق الحد الأوسط، فالعائلات الحية الأخرى كالثدييات المائية تعيش بالماء أيضاً.', 'beginner', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مغالطات المنطق الصوري', 'LOG-0044', true, 1),
  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'إذا سار شخص باتجاه الشمال 4 كم، ثم اتجه شرقاً وسار 3 كم، فكم يبعد عن نقطة البداية خطاً مستقيماً؟', '["5 كم","7 كم","1 كم","12 كم"]'::jsonb, 0, 20, 166, 'multi', 'باستخدام مبرهنة فيثاغورس الجذر التربيعي لـ (4² + 3²) = √(16+9) = √25 = 5 كم.', 'beginner', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'الهندسة وحساب المسافات المنطقية', 'LOG-0048', true, 1),
  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'إذا كانت 5 آلات تستغرق 5 دقائق لصنع 5 قطعة، فكم دقيقة تستغرق 100 آلة لصنع 100 قطعة؟', '["100 دقيقة","50 دقيقة","1 دقيقة","5 دقائق"]'::jsonb, 3, 20, 167, 'multi', 'كل آلة واحدة تستغرق 5 دقائق لصنع قطعة واحدة. بالتالي 100 آلة تعمل بالتوازي تصنع 100 قطعة في 5 دقائق أيضاً.', 'beginner', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل التناسب والزمن والعمل', 'LOG-0051', true, 1),
  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'إذا كان سعر القلم والدفتر معاً 11 ريالاً، وكان سعر الدفتر يزيد عن القلم بـ 10 ريالات، فكم سعر القلم؟', '["0.5 ريال (نصف ريال)","ريال واحد","2 ريال","1.5 ريال"]'::jsonb, 0, 20, 168, 'multi', 'القلم س والدفتر س+10. س + س + 10 = 11 -> 2س = 1 -> س = 0.5 ريال (والدفتر 10.5 ريال).', 'beginner', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'اختبار التفكير السريع والمنطق الذهني', 'LOG-0052', true, 1),
  ('e7152dd4-8031-4c2c-a1a4-04c6f50563a8', 'مغالطة رجل القش (Straw Man) تقوم على تشويه حجة الخصم وتبسيطها وتضعيفها ثم الهجوم على هذا التشويه بدلاً من الحجة الأصلية.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 169, 'multi', 'أسلوب شائع في المناظرات والجدل غير الموضوعي.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'المغالطات المنطقية - عادل مصطفى', 'LOG-0063', true, 2),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما اسم المغالطة التي تنص على أن الشيء صحيح لمجرد أن أغلبية الناس أو الجمهور يؤمنون بصحته؟', '["مغالطة الاحتكام إلى الأغلبية / الكثرة","مغالطة السلطة","مغالطة الجهل","مغالطة المنحدر الزلق"]'::jsonb, 0, 20, 170, 'multi', 'الكثرة لا تعتبر إثباتاً للصح والخطأ في المنهج العلمي والمنطقي.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Logic and Critical Thinking Guide', 'LOG-0064', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'مغالطة التوسل بالجهل (Argument from Ignorance) تعتبر أن الشيء صحيح لمجرد أنه لم يثبت بطلانه بعد.', '["صح","خطأ"]'::jsonb, 0, 20, 171, 'boolean', 'عدم وجود الدليل على عدم الشيء ليس دليلاً على وجوده.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'The Art of Reasoning', 'LOG-0066', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما اسم المغالطة التي تقوم على تقديم خيارين اثنين فقط للحل أو الموقف مع وجود خيارات متعددة أخرى؟', '["مغالطة السؤال المركب","مغالطة التعميم","مغالطة السبب الزائف","مغالطة المعضلة الزائفة / إما أو"]'::jsonb, 3, 20, 172, 'multi', 'تضييق الخيارات عمداً على الطرف الآخر لإجباره على اتخاذ موقف معين.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Critical Thinking & Logic', 'LOG-0067', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما اسم المغالطة التي تقوم على افتراض أن الحل الوسط بين رأيين متناقضين هو الصواب دائماً لمجرد أنه وسط؟', '["مغالطة المعضلة","مغالطة التركيب","مغالطة الوسط الذهبي الزائف","مغالطة التقسيم"]'::jsonb, 2, 20, 173, 'multi', 'ليس كل حل وسط صحيحاً فقد يكون أحد الطرفين هو الصواب المطلق والآخر باطلاً.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Fallacies Guide', 'LOG-0074', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'التفكير الاستقرائي (Inductive Reasoning) ينقل العقل من ملاحظة الحالات الخاصة والجزئيات إلى تعميم حكم عام.', '["صح","خطأ"]'::jsonb, 0, 20, 174, 'boolean', 'حجر الأساس للاستكشاف والمنهج التجريبي العلمي.', 'beginner', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Scientific Method & Induction', 'LOG-0078', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما هو المفهوم العلمي/المعرفي المتقدم المتعلق بـ المتتاليات ومتتابعات الأرقام رقم 1006؟', '["المفهوم الثاني الخاطئ","المفهوم الثالث الخاطئ","المفهوم الأول الصحيح","المفهوم الرابع الخاطئ"]'::jsonb, 2, 20, 175, 'multi', 'شرح توضيحي دقيق للمفهوم في المتتاليات ومتتابعات الأرقام.', 'beginner', 'متتاليات رقمية', '{"منطق وذكاء","متتاليات رقمية"}'::text[], 'الموسوعة المعرفية الموثقة', 'LOG-QA1005', true, 1),
