  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'إذا تم تدوير مكعب يحتوي على وجه أحمر في الأعلى بزاوية 90 درجة للأمام، فأين يصبح الوجه الأحمر؟', '["في الوجه الأمامي المقابل","في الأسفل","في الخلف","على اليمين"]'::jsonb, 0, 20, 178, 'multi', 'التدوير للأمام بنصف دورة قائمة ينقل السطح العلوي للواجهة الأمامية.', 'beginner', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'اختبارات التصور الفضائي والمكاني', 'LOG-0104', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما عدد الأوجه الظاهرة للمكعب عند النظر إليه من زاوية قطرية ثلاثية الأبعاد في أقصى حد؟', '["4 أوجه","3 أوجه","2 وجهين","6 أوجه"]'::jsonb, 1, 20, 179, 'multi', 'لا يمكن في المنظور البصري المستقيم رؤية أكثر من 3 أوجه للمكعب في نفس الوقت.', 'beginner', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'Spatial Vision & Geometry', 'LOG-0109', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'دوران مثلث قائم الزاوية حول أحد ضلعي الزاوية القائمة ينشئ مجسماً كروياً.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 180, 'multi', 'دوران المثلث القائم ينشئ مخروطاً وليس كرة.', 'beginner', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'Geometry Solids of Revolution', 'LOG-0111', true, 2),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'القطع المستوي المائل لأسطوانة قائمة بصل لجميع جوانبها ينشئ مقطعاً على شكل قطع ناقص (إهليلج).', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 181, 'multi', 'حقيقة هندسية لمقاطع الأسطوانة المائلة.', 'beginner', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'Conic Sections & Cross Sections', 'LOG-0115', true, 2),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'ما اسم التحويل الهندسي الذي ينقل جميع نقاط الشكل مسافة متساوية في اتجاه معين دون تدويره؟', '["الإزاحة / الانسحاب","الدوران","الانعكاس","التكبير"]'::jsonb, 0, 20, 182, 'multi', 'حافظ على القياسات والاتجاهات بالكامل.', 'beginner', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'Transformational Geometry', 'LOG-0124', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'تاجر اشترى بضعة بـ 80 ريالاً وباعها بـ 100 ريال. ما هي نسبة ربحه المئوية مقارنة بسعر الشراء؟', '["25%","20%","15%","30%"]'::jsonb, 0, 20, 183, 'multi', 'مقدار الربح = 100 - 80 = 20 ريالاً. نسبة الربح = (20 ÷ 80) × 100 = 25%.', 'beginner', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الربح والخسارة والنسبة', 'LOG-0128', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'إذا كان عمر فهد الآن ثلاثة أضعاف عمر سعد، وبعد 5 سنوات يصبح مجموع عمريهما 50 سنة، فكم عمر سعد الآن؟', '["8 سنوات","12 سنة","15 سنة","10 سنوات"]'::jsonb, 3, 20, 184, 'multi', 'الآن: سعد س، فهد 3س. بعد 5 سنوات: (س+5) + (3س+5) = 50 -> 4س + 10 = 50 -> 4س = 40 -> س = 10 سنوات.', 'beginner', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الأعمار والتناسب الكلامي', 'LOG-0135', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'صندوق يحتوي على كرة حمراء وكرة خضراء وكرة زرقاء. إذا سحبت كرتان معاً عشوائياً، فما احتمال ألا تكون الكرة الحمراء بينهما؟', '["1/3","2/3","1/2","1/6"]'::jsonb, 0, 20, 185, 'multi', 'عدد طرق سحب كرتين من 3 هو 3 طرق. النتيجة الوحيدة لعدم وجود الحمراء هي سحب (خضراء وزرقاء) أي طريقة واحدة = 1/3.', 'beginner', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الاحتمال والتجميع الكلامي', 'LOG-0144', true, 1),
  ('4b586ac8-7514-4822-aff8-8a873ff9e27f', 'حافلة ركبها 20 شخصاً في المحطة الأولى. في المحطة الثانية نزل نصفهم وركب 5 جدد. كم شخصاً بالحافلة الآن؟', '["10 أشخاص","15 شخصاً","25 شخصاً","20 شخصاً"]'::jsonb, 1, 20, 186, 'multi', '20 - 10 (النصف) = 10 + 5 جدد = 15 شخصاً.', 'beginner', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل التتبع الحسابي البسيط', 'LOG-0145', true, 1),
