  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'لدينا ثلاثة صناديق: أسود، أبيض، أحمر. إذا كانت الكرة ليست في الأسود وليست في الأبيض، فأين تكون الكرة حتماً؟', '["في الصندوق الأسود","في الصندوق الأبيض","خارج الصناديق","في الصندوق الأحمر"]'::jsonb, 3, 20, 223, 'multi', 'باستبعاد الصندوقين الأسود والأبيض تبقى الخيار الوحيد وهو الصندوق الأحمر.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'اختبارات الذكاء المنهجية', 'LOG-0043', true, 1),
  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'إذا كان اليوم هو الثلاثاء، فما اليوم الذي سيكون بعد 10 أيام من الآن؟', '["السبت","الجمعة","الخميس","الأحد"]'::jsonb, 1, 20, 224, 'multi', '10 أيام تعادل أسبوعاً كاملاً (7 أيام) + 3 أيام. الثلاثاء + 3 أيام = الجمعة.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'الحساب الذهني وتطبيقات الأيام', 'LOG-0045', true, 1),
  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'ساعة حائط تتأخر بمقدار 5 دقائق كل ساعة. إذا تم ضبطها عند الساعة 12 ظهراً، فكم ستكون القراءة الصحيحة عندما تشير الساعة لـ 3:45 عصراً؟', '["الساعة 3:30","الساعة 4:15","الساعة 4:00 عصراً","الساعة 3:45"]'::jsonb, 2, 20, 225, 'multi', 'في كل ساعة حقيقية 60 دقيقة تقرأ الساعة 55 دقيقة. 3:45 تعادل 225 دقيقة قراءة = 4 ساعات حقيقية (4:00).', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل الوقت والنسب المنطقية', 'LOG-0046', true, 1),
  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'إذا كان لديك 8 كرات متطابقة بالكامل للشكل، وواحدة منها أثقل قليلاً، فما أقل عدد مرات ميزان بكفتين لمعرفة الكرة الثقيلة حتماً؟', '["3 مرات","4 مرات","مرتان فقط","مرة واحدة"]'::jsonb, 2, 20, 226, 'multi', 'نقسم الكرات إلى 3 و 3 و 2. الوزنة الأولى تقارن 3 ضد 3 فتحدد المجموعة الثقيلة، ثم الوزنة الثانية تحسمها.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'أحجيات الوزن والموازين التكتيكية', 'LOG-0054', true, 1),
  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'إذا تضاعف عدد البكتيريا في كوب كل دقيقة، وتمتلئ الكوب بالكامل بعد 60 دقيقة، فمتى تكون الكوب ممتلئة لنصفها؟', '["بعد 30 دقيقة","بعد 15 دقيقة","بعد 45 دقيقة","بعد 59 دقيقة"]'::jsonb, 3, 20, 227, 'multi', 'بما أن عدد البكتيريا يتضاعف كل دقيقة، ففي الدقيقة 59 كانت النصف، وفي الدقيقة 60 تضاعفت لتصبح الكوب كاملة.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'النمو الأسي والمنطق العكسي', 'LOG-0055', true, 1),
  ('716e5328-dff6-4f87-a784-bd2bf91968c8', 'إذا كان حاصل ضرب عدديين صحيحين هو 12، ومجموعهما 7، فما هما العددان؟', '["2 و 6","3 و 4","1 و 12","5 و 2"]'::jsonb, 1, 20, 228, 'multi', '3 × 4 = 12 و 3 + 4 = 7.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المعادلات الرقمية الذهنية السريعة', 'LOG-0057', true, 1),
  ('54032ee3-e537-4edd-a0a9-f360c55ea8ec', 'إذا كان لجميع الكلاب أربعة أرجل، وجميع القطط لها أربعة أرجل، فإن جميع الكلاب قطط.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 229, 'multi', 'نتيجة خاطئة تماماً منطقياً لعدم وجود علاقة احتواء بين المجموعتين.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المنطق الصوري والمجموعات', 'LOG-0059', true, 2),
  ('54032ee3-e537-4edd-a0a9-f360c55ea8ec', 'إذا تجاوزت المتسابق صاحب المركز الثاني في سباق جري، فما هو مركزك الحالي في السباق؟', '["المركز الثاني","المركز الأول","المركز الثالث","المركز أخير"]'::jsonb, 0, 20, 230, 'multi', 'عندما تتجاوز صاحب المركز الثاني فأنت تأخذ مكانه وتصبح في المركز الثاني وهو يصبح في الثالث.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'ألغاز التفكير المباشر والتحدي', 'LOG-0060', true, 1),
  ('54032ee3-e537-4edd-a0a9-f360c55ea8ec', 'أب عمره أربعة أضعاف عمر ابنه. بعد 20 سنة، يصبح عمر الأب ضعفي عمر ابنه. كم عمر الابن الآن؟', '["5 سنوات","10 سنوات","15 سنة","20 سنة"]'::jsonb, 1, 20, 231, 'multi', 'الآن: الابن س والأب 4س. بعد 20 سنة: 4س + 20 = 2(س + 20) -> 4س + 20 = 2س + 40 -> 2س = 20 -> س = 10 سنوات.', 'standard', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل الأعمار المنطقية', 'LOG-0061', true, 1),
