  ('43588e3b-497b-431a-ab9f-414c722b4e4d', 'إذا كانت النملة تتسلق جداراً ارتفاعه 10 أمتار، تتسلق 3 أمتار بالنهار وتنزلق مترين بالليل، ففي كم يوماً تصل لأعلى الجدار؟', '["10 أيام","في 8 أيام","5 أيام","9 أيام"]'::jsonb, 1, 20, 329, 'multi', 'في اليوم الأول تصل لـ 1م الصافي. في نهاية اليوم 7 تصل لـ 7م. في نهار اليوم 8 تتسلق 3م فتصل 10م وتخرج قبل انزلاق الليل.', 'challenge', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'أحجيات الحركة والمسافات الكلاسيكية', 'LOG-0049', true, 1),
  ('43588e3b-497b-431a-ab9f-414c722b4e4d', 'إذا كان مجموع عمري أب وابنه 45 سنة، وكان عمر الأب يزيد عن عمر ابنه بـ 35 سنة، فكم عمر الابن؟', '["10 سنوات","2.5 سنة","5 سنوات","7 سنوات"]'::jsonb, 2, 20, 330, 'multi', 'س (الأب) + ص (الابن) = 45، س - ص = 35. بطرح المعادلتين 2ص = 10 إذاً ص = 5 سنوات (والأب 40).', 'challenge', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المعادلات الكلامية الذكية', 'LOG-0050', true, 1),
